import { Component, OnInit } from '@angular/core';
import { Cart, CartService } from '../../services/cart.service';

@Component({
  selector: 'app-cart',
  templateUrl: './cart.component.html',
  styleUrls: ['./cart.component.css']
})
export class CartComponent implements OnInit {

  cart: Cart = {
    items: []
  };

  orderPlaced = false;

  orderedItems: any[] = [];

  // RIGHT-SIDE INGREDIENT DROPDOWN
  showSummaryIngredients = false;


  constructor(
    private cartService: CartService
  ) {}


  ngOnInit(): void {
    this.loadCart();
  }


  loadCart(): void {

    this.cartService.getCart().subscribe({

      next: (data) => {
        this.cart = data;
      },

      error: (error) => {
        console.error(
          'Failed to load cart:',
          error
        );
      }

    });

  }


  isNonVeg(type: string): boolean {

    const value = type?.toLowerCase().trim();

    return value === 'non-veg' ||
           value === 'nonveg' ||
           value === 'non veg';

  }


  // =========================================
  // LEFT INGREDIENT DROPDOWN
  // =========================================

  toggleIngredients(item: any): void {

    item.showIngredients =
      !item.showIngredients;

  }


  // =========================================
  // RIGHT INGREDIENT DROPDOWN
  // =========================================

  toggleSummaryIngredients(): void {

    this.showSummaryIngredients =
      !this.showSummaryIngredients;

  }


  // =========================================
  // GET ALL INGREDIENTS FROM CART
  // =========================================

  getAllIngredients(): any[] {

    const ingredients: any[] = [];

    this.cart.items.forEach(item => {

      if (
        item.ingredients &&
        item.ingredients.length > 0
      ) {

        ingredients.push(
          ...item.ingredients
        );

      }

    });

    return ingredients;

  }


  // =========================================
  // UPDATE QUANTITY
  // =========================================

  updateQuantity(
    itemId: string,
    quantity: number
  ): void {

    if (quantity === 0) {

      this.removeItem(itemId);

      return;

    }

    if (quantity < 0) {
      return;
    }

    this.cartService
      .updateQuantity(itemId, quantity)
      .subscribe({

        next: (data) => {
          this.cart = data;
        },

        error: (error) => {

          console.error(
            'Failed to update quantity:',
            error
          );

        }

      });

  }


  // =========================================
  // REMOVE ITEM
  // =========================================

  removeItem(itemId: string): void {

    this.cartService
      .removeFromCart(itemId)
      .subscribe({

        next: (data) => {
          this.cart = data;
        },

        error: (error) => {

          console.error(
            'Failed to remove item:',
            error
          );

        }

      });

  }


  // =========================================
  // PIZZA TOTAL
  // =========================================

  getPizzaTotal(): number {

    return this.cart.items.reduce(
      (total, item) =>
        total +
        (item.price * item.quantity),
      0
    );

  }


  // =========================================
  // INGREDIENT TOTAL
  // =========================================

  getIngredientsTotal(): number {

    return this.cart.items.reduce(
      (total, item) => {

        const ingredientTotal =
          item.ingredients
            ? item.ingredients.reduce(
                (sum: number, ingredient: any) =>
                  sum + ingredient.price,
                0
              )
            : 0;

        return total +
          (ingredientTotal * item.quantity);

      },
      0
    );

  }


  // =========================================
  // GRAND TOTAL
  // =========================================

  getTotal(): number {

    return (
      this.getPizzaTotal() +
      this.getIngredientsTotal()
    );

  }


  // =========================================
  // CHECKOUT
  // =========================================

  checkout(): void {

    console.log(
      'Pay button clicked'
    );

    if (this.cart.items.length === 0) {

      alert(
        'Your cart is empty'
      );

      return;

    }

    this.orderedItems =
      [...this.cart.items];

    this.cartService
      .clearCart()
      .subscribe({

        next: () => {

          console.log(
            'Order placed'
          );

          this.cart = {
            items: []
          };

          this.orderPlaced = true;

        },

        error: (error) => {

          console.error(
            'Failed to place order:',
            error
          );

          alert(
            'Something went wrong while placing the order.'
          );

        }

      });

  }


  // =========================================
  // CLEAR CART
  // =========================================

  clearCart(): void {

    if (this.cart.items.length === 0) {
      return;
    }

    this.cartService
      .clearCart()
      .subscribe({

        next: (data) => {
          this.cart = data;
        },

        error: (error) => {

          console.error(
            'Failed to clear cart:',
            error
          );

        }

      });

  }

}
